{
  "technical_and_design_decisions": [
    "For the Solo ordering process (U4), use a single-threaded block creation routine consuming from a buffered transaction channel, with an in-memory append-only ledger that stores block data and supports seek operations via client-provided block numbers or transaction IDs.",
    "For the standalone CLI tool (U8), separate CLI command implementations into an independent Go package that only depends on public Fabric SDK interfaces, eliminating direct dependencies on peer node internals and RocksDB.",
    "For the state cache (U6), implement a read-through LRU (Least Recently Used) cache that sits between the rw-set builder and the world state storage, with invalidation triggered on chaincode commit events to ensure cache consistency.",
    "For the chaincode friendly name feature (U1), store friendly names as part of chaincode definition metadata in the channel's configuration, with uniqueness enforced per channel to avoid naming conflicts.",
    "For the lifecycle system chaincode extension (U2), reuse existing access control policies from the Fabric lifecycle module to restrict policy management operations to channel administrators.",
    "For the public GitHub repository (U5), use a one-way sync from the main Gerrit repository to GitHub to ensure the public repo remains a consistent mirror of the official codebase.",
    "For the centralized documentation (U7), use a static site generator (Docusaurus) with versioned documentation support to host all Hyperledger project docs under the hyperledger.org domain.",
    "For the upgrade flow documentation (U3), align documentation content with existing Fabric v2.x upgrade procedures to ensure consistency with current product behavior."
  ],
  "assumptions": [
    "The development team has full access to the existing Hyperledger Fabric Gerrit repository and all associated internal documentation and test frameworks.",
    "The Solo ordering process is intended for development and testing use cases only, so no production-grade persistence or fault tolerance is required for the in-memory ledger.",
    "The public GitHub repository will not accept direct contributions, all code changes will continue to be submitted via the main Gerrit repository.",
    "The state cache implementation will not modify the underlying world state database (e.g., CouchDB, LevelDB) and will only add a caching layer on top of existing read APIs.",
    "The standalone CLI tool will support all existing peer commands related to chaincode, channel, and identity management, with no feature reduction from the current peer-embedded CLI.",
    "Existing Fabric test infrastructure (including test networks and integration test suites) can be reused for testing all new features without additional setup.",
    "The hyperledger.org documentation site already has existing hosting infrastructure in place, so only content migration and configuration are required.",
    "All new features are compatible with the existing Fabric v2.x API surface, with no breaking changes to public APIs for existing users."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement chaincode friendly name feature",
      "activity_description": "Add a friendly name field to chaincode definition metadata stored in channel configuration, update chaincode registration, query, and listing APIs to support lookup by friendly name, and implement validation to ensure friendly names are unique per channel.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Extend lifecycle system chaincode for deployment policy management",
      "activity_description": "Extend the existing Fabric lifecycle system chaincode (SCC) with new functions to define, query, and update chaincode deployment policies, implement access control to restrict policy management to channel administrators, and add validation logic for policy definitions.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A3",
      "activity_name": "Write chaincode upgrade flow documentation",
      "activity_description": "Create comprehensive documentation for the Fabric chaincode upgrade flow, including pre-upgrade requirements, policy configuration, step-by-step upgrade execution commands, rollback procedures, and sample use cases.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement Solo ordering process",
      "activity_description": "Implement a lightweight Solo ordering process for development/testing use cases, including a buffered channel for transaction ingestion, single-threaded block creation logic, in-memory append-only ledger with seek API for block/transaction lookup, client offset tracking to support disconnection and reconnection, and basic integration tests for orderer functionality.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5",
      "activity_name": "Set up public GitHub mirror for Fabric codebase",
      "activity_description": "Configure a read-only mirror of the main Gerrit-hosted Hyperledger Fabric repository on public GitHub, set up a CI/CD pipeline to one-way sync changes from Gerrit to GitHub, and add contribution guidelines and issue templates for the public repository.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6",
      "activity_name": "Implement state cache for rw-set generation",
      "activity_description": "Implement a read-through LRU state cache that interfaces with the existing world state storage, add cache invalidation logic triggered on chaincode commit/update events, expose a public cache API for the rw-set builder to consume, and implement unit tests for cache hit/miss scenarios and invalidation correctness.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A7",
      "activity_name": "Consolidate Hyperledger documentation on hyperledger.org",
      "activity_description": "Set up a centralized Docusaurus-based documentation site hosted on hyperledger.org, migrate existing Hyperledger project (including Fabric) documentation to the new site, and add cross-project navigation and full-text search functionality.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8",
      "activity_name": "Develop standalone Fabric CLI tool",
      "activity_description": "Extract existing peer CLI commands into a standalone, platform-agnostic Go module, decouple command logic from peer node internal dependencies and RocksDB linkage, implement CI/CD pipelines for building Mac and Windows platform-specific binaries, and add integration tests for core CLI commands.",
      "most_likely_effort": 7
    }
  ],
  "reported_total": {
    "most_likely_effort": 37
  }
}

